public class ErpSyncFinalizer implements System.Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(System.FinalizerContext context) {
        FB_Job_Log__c logEntry = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt
        );

        Exception ex = context.getException();
        if (ex != null) {
            logEntry.Status__c = 'Failed';
            String errMsg = ex.getMessage();
            logEntry.Error__c = (errMsg != null && errMsg.length() > 255)
                ? errMsg.left(255)
                : errMsg;

            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        } else {
            logEntry.Status__c = 'Success';
        }

        insert logEntry;
    }
}
