public without sharing class OpportunityPipelineHandler {

    private static Boolean running = false;

    public static void handle(List<Opportunity> newRecords, List<Opportunity> oldRecords,
                              Boolean isInsert, Boolean isUpdate, Boolean isDelete, Boolean isUndelete) {
        if (running) return;
        running = true;
        try {
            Set<Id> accountIds = collectAffectedAccountIds(
                newRecords, oldRecords, isInsert, isUpdate, isDelete, isUndelete);
            if (accountIds.isEmpty()) return;
            recalculateAccounts(accountIds);
        } finally {
            running = false;
        }
    }

    private static Set<Id> collectAffectedAccountIds(
            List<Opportunity> newRecords, List<Opportunity> oldRecords,
            Boolean isInsert, Boolean isUpdate, Boolean isDelete, Boolean isUndelete) {

        Set<Id> accountIds = new Set<Id>();

        if (isInsert) {
            for (Opportunity o : newRecords) {
                if (o.IsClosed == false && o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (isUpdate) {
            for (Integer i = 0; i < newRecords.size(); i++) {
                Opportunity newOpp = newRecords[i];
                Opportunity oldOpp = oldRecords[i];

                if (newOpp.AccountId != oldOpp.AccountId) {
                    if (oldOpp.AccountId != null) accountIds.add(oldOpp.AccountId);
                    if (newOpp.AccountId != null) accountIds.add(newOpp.AccountId);
                } else if (newOpp.AccountId != null
                           && (oldOpp.IsClosed != newOpp.IsClosed
                               || oldOpp.Amount != newOpp.Amount)) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        } else if (isDelete) {
            for (Opportunity o : oldRecords) {
                if (o.IsClosed == false && o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        } else if (isUndelete) {
            for (Opportunity o : newRecords) {
                if (o.IsClosed == false && o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        return accountIds;
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
        Map<Id, Integer> countMap = new Map<Id, Integer>();

        for (Opportunity o : [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
        ]) {
            Decimal amt = o.Amount != null ? o.Amount : 0;
            pipelineMap.put(o.AccountId, (pipelineMap.get(o.AccountId) ?? 0) + amt);
            countMap.put(o.AccountId, (countMap.get(o.AccountId) ?? 0) + 1);
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            Account acc = new Account(Id = accountId);
            acc.FB_Open_Pipeline__c = pipelineMap.get(accountId) ?? 0;
            acc.FB_Open_Opportunities__c = countMap.get(accountId) ?? 0;
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

### The fix

The single-line change is in the SOQL loop:

```apex
// Before (NPE on first occurrence of an account):
countMap.put(o.AccountId, countMap.get(o.AccountId) + 1);

// After:
countMap.put(o.AccountId, (countMap.get(o.AccountId) ?? 0) + 1);
```

When building a map in a loop, the first time a key is seen, `Map.get()` returns `null`. The `?? 0` null-coalescing operator ensures the first insert writes `1` instead of throwing. The same pattern was already correctly applied to `pipelineMap` but was missed on `countMap`.

Looking at the errors, I need to fix several issues:

1. Missing interface methods (`registerPermanentlyDeleted`, `registerPublish*`, `registerWork`, `registerEmail`)
2. `commitWork()` must return `void`, not `Map<Id, List<String>>`
3. `@Setup` annotation not available - use a helper method instead
4. `fflib_ApexMocks` methods are instance methods, not static
5. `fflib_IDGenerator.newId()` takes a `Type` (class literal), not `SObjectType`
6. `System.assertSameInstance` doesn't exist - use `==` for reference equality
7. `Schema.SObjectField` comparison needs `System.assert` instead of `assertEquals`

