public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    private List<String> getCreditReviewFieldNames() {
        // Fields in the Account.Credit_Review field set.
        // Keep in sync with the field set when admins add/remove fields in Setup.
        // (The Apex Schema API does not expose field set membership at runtime.)
        return new List<String>{
            'AnnualRevenue',
            'Rating'
        };
    }

    private List<String> getAllFieldNames() {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            names.add(field.getDescribe().getName());
        }
        for (String name : getCreditReviewFieldNames()) {
            if (!names.contains(name)) {
                names.add(name);
            }
        }
        return names;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        String query = 'SELECT ' + String.join(getAllFieldNames(), ', ')
            + ' FROM Account WITH USER MODE WHERE Id IN :accountIds';
        return (List<Account>) Database.query(query);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : contactsSelector.getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }
        String subquery = '(SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)';
        String query = 'SELECT ' + String.join(getAllFieldNames(), ', ') + ', ' + subquery
            + ' FROM Account WITH USER MODE WHERE Id IN :accountIds';
        return (List<Account>) Database.query(query);
    }
}
