public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * Stages and processes one NPSP Data Import record per gift synchronously,
     * then returns one ImportResult per gift in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ── 1. Stage one DataImport record per gift ──────────────────────────
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            );
            dataImports.add(di);
        }

        // Persist the staged records so they remain as the audit trail.
        insert dataImports;

        // ── 2. Process synchronously via NPSP's Data Import API ──────────────
        // NPSP applies the org's Data Import settings (match on first name,
        // last name, email; never match existing donations) automatically.
        List<Id> importIds = new List<Id>();
        for (npsp__DataImport__c di : dataImports) {
            importIds.add(di.Id);
        }

        npsp__BDIDataImportService processor = new npsp__BDIDataImportService();
        processor.processImport(importIds);

        // ── 3. Read back NPSP's per-row results ───────────────────────────────
        Map<Id, npsp__DataImport__c> resultMap =
            new Map<Id, npsp__DataImport__c>(
                [SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                 FROM npsp__DataImport__c
                 WHERE Id IN :importIds]
            );

        // ── 4. Build results in input order ───────────────────────────────────
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < dataImports.size(); i++) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c di = resultMap.get(dataImports[i].Id);

            if (di != null) {
                result.success       = 'Imported' == di.npsp__Status__c;
                result.contactId     = di.npsp__Contact1Imported__c;
                result.opportunityId = di.npsp__DonationImported__c;
                result.errorMessage  = di.npsp__FailureInformation__c;
            } else {
                result.success      = false;
                result.errorMessage = 'DataImport record not found after processing';
            }

            results.add(result);
        }

        return results;
    }
}
